drive={'googleDriveOAuth2Api': {'id': 'VcVRAhAAnk2YcHNE', 'name': 'Google Drive account 3'}}
node('Dateien abgleichen','webhook',{'httpMethod':'POST','path':'sma-publication-files-v1','responseMode':'responseNode','options':{'allowedOrigins':'https://sma-automation.com'}},0,v=2.1,webhookId=str(uuid.uuid4()))
code('Anfrage prüfen',"const a=$input.first().json.headers?.authorization;return [{json:typeof a==='string'&&/^Bearer [A-Za-z0-9._-]{20,8000}$/.test(a)?{ok:true,auth:a}:{ok:false,code:'AUTH_REQUIRED'}}];",220)
